/* Native avatar family, sized to the shadcn Base Nova reference.
   Reference: https://ui.shadcn.com/r/styles/base-nova/avatar.json
   No component framework or runtime network request is required.
   User-supplied portrait, original PNG bytes preserved. Cropping is CSS only.
   The same photograph is used in every demo and group. The shared UserFill
   placeholder is official Hugeicons Stroke Rounded geometry, not a generated illustration. */
(function(F){
 'use strict';
 const portrait="data:image/png;base64,";
 const samples=[{"name":"Alex Morgan","initials":"AM"},{"name":"Sam Kim","initials":"SK"},{"name":"Jordan Davis","initials":"JD"},{"name":"Maya Rivera","initials":"MR"},{"name":"Priya Chen","initials":"PC"},{"name":"Taylor Wong","initials":"TW"},{"name":"Riley Brown","initials":"RB"},{"name":"Lee Nguyen","initials":"LN"}];
 const E=F.escape;
 F.avatarTones={neutral:['gray.200','gray.900'],warning:['amber.100','amber.900'],blue:['blue.200','blue.900'],sky:['sky.200','sky.900'],purple:['purple.200','purple.900'],danger:['red.200','red.900'],success:['green.200','green.900']};
 for(const [tone,values]of Object.entries(F.avatarTones))for(const [index,role]of ['background','foreground'].entries())F.addToken(`semantic.avatar.${tone}.${role}`,'color',`{color.${values[index]}}`,'normalized');
 const aliases={
  'avatar.background':'semantic.avatar.blue.background','avatar.foreground':'semantic.avatar.blue.foreground',
  'avatar.border':'semantic.border.default','avatar.border.width':'border.width',
  'avatar.ring':'semantic.surface.default','avatar.ring.width':'space.2',
  'avatar.radius.circle':'radius.full','avatar.radius.square':'radius.lg',
  'avatar.weight':'font.weight.500','avatar.size.sm':'space.24','avatar.size.md':'space.32','avatar.size.lg':'space.40',
  'avatar.font.sm':'font.size.12','avatar.font.md':'font.size.14','avatar.font.lg':'font.size.14',
  'avatar.badge.size.sm':'space.8','avatar.badge.size.md':'size.10','avatar.badge.size.lg':'space.12',
  'avatar.badge.icon':'size.10','avatar.badge.foreground':'semantic.text.inverse','avatar.badge.mark.stroke':'icon.stroke.small',
  'avatar.badge.icon.size.sm':'space.12','avatar.badge.icon.size.md':'size.14','avatar.badge.icon.size.lg':'space.16',
  'avatar.badge.mark.sm':'space.8','avatar.badge.mark.md':'size.10','avatar.badge.mark.lg':'space.12',
  'avatar.placeholder.foreground':'semantic.text.inverse',
  'avatar.group.overlap':'space.8','avatar.group.count.background':'semantic.surface.subtle',
  'avatar.group.count.foreground':'semantic.text.secondary',
  'avatar.group.icon.sm':'space.12','avatar.group.icon.md':'space.16','avatar.group.icon.lg':'space.20'
 };
 for(const tone of Object.keys(F.badgeTones)){
  aliases[`avatar.badge.${tone}.background`]=`semantic.badge.${tone}.indicator`;
  aliases[`avatar.badge.${tone}.icon.background`]=`semantic.badge.${tone}.indicator`;
  aliases[`avatar.badge.${tone}.foreground`]=tone==='success'?'color.green.900':tone==='warning'?'color.amber.900':'semantic.text.inverse';
 }
 for(const tone of Object.keys(F.avatarTones))for(const role of ['background','foreground'])aliases[`avatar.${tone}.${role}`]=`semantic.avatar.${tone}.${role}`;
 for(const [id,target]of Object.entries(aliases))F.addToken('component.'+id,F.tokens[target].type,`{${target}}`,'normalized');
 const sizeOf=c=>['sm','lg'].includes(c.size)?c.size:'md';
 const badgeOf=c=>['dot','icon'].includes(c.badge)?c.badge:c.online?'dot':'none';
 const toneOf=c=>F.badgeTones[c.badgeTone]?c.badgeTone:'success';
 const colorOf=c=>F.avatarTones[c.tone]?c.tone:'blue';
 const tokensOf=c=>{
  const size=sizeOf(c),map={size:'component.avatar.size.'+size,font:'component.avatar.font.'+size,weight:'component.avatar.weight',
   background:'component.avatar.'+colorOf(c)+'.background',foreground:'component.avatar.'+colorOf(c)+'.foreground',border:'component.avatar.border',
   'border-width':'component.avatar.border.width',radius:'component.avatar.radius.'+(c.shape==='square'?'square':'circle')};
  if(badgeOf(c)!=='none')Object.assign(map,{
   'badge-size':'component.avatar.badge.'+(badgeOf(c)==='icon'?'icon.':'')+'size.'+size,'badge-background':'component.avatar.badge.'+toneOf(c)+'.background','badge-radius':'component.avatar.radius.circle',
   ring:'component.avatar.ring','ring-width':'component.avatar.ring.width'
  });
  if(badgeOf(c)==='icon')Object.assign(map,{'badge-icon':'component.avatar.badge.mark.'+size,'badge-foreground':'component.avatar.badge.'+toneOf(c)+'.foreground','badge-mark-stroke':'component.avatar.badge.mark.stroke'});
  if(c.variant==='placeholder')map['placeholder-foreground']='component.avatar.placeholder.foreground';
  return map;
 };
 const styles=map=>Object.entries(map).map(([key,id])=>`--avatar-${key}:${F.v(id)}`).join(';');
 const countOf=value=>Math.max(1,Math.min(8,Math.floor(Number(value)||4)));
 const overflowOf=value=>Math.max(0,Math.min(999,Math.floor(value===undefined?3:Number(value)||0)));
 const safeSource=value=>{
  const src=String(value??'').trim();
  return /^(?:https?:\/\/|data:image\/(?:png|jpe?g|webp|gif|avif);base64,|\.\.?\/|\/)/i.test(src)?src:'';
 };
 const initialsOf=(value,name)=>{
  const explicit=String(value??'').trim();
  return (explicit||String(name).trim().split(/\s+/).map(part=>part[0]||'').join('')||'U').slice(0,2).toUpperCase();
 };
 F.avatarTokens=(c={})=>['font.family.sans',...new Set(Object.values(tokensOf(c)))];
 F.avatar=(c={})=>{
  const size=sizeOf(c),sample=samples[Math.abs(Math.floor(Number(c.sample)||0))%samples.length];
  const isImage=c.variant==='image',name=String(c.name||(!c.initials&&isImage?sample.name:c.initials)||'User');
  const initials=initialsOf(c.initials||(isImage&&!c.name?sample.initials:''),name),badge=badgeOf(c);
  const icon=['check','bolt'].includes(c.iconName)?c.iconName:'check';
  const badgeLabel=c.badgeLabel||(badge==='icon'?(icon==='check'?'Verified':'Active'):(toneOf(c)==='success'?'Online':'Status indicator'));
  const label=name+(badge!=='none'?', '+badgeLabel:'');
  const samplePhoto=isImage&&(c.src===undefined||c.src===''),src=isImage?safeSource(samplePhoto?portrait:c.src):'';
  const fallback=c.variant==='placeholder'?`<span class="pp-avatar-placeholder" aria-hidden="true">${F.icon('user-fill',parseFloat(F.resolve('component.avatar.size.'+size)))}</span>`:E(initials);
  return `<span class="pp-avatar pp-avatar-root size-${size} ${c.shape==='square'?'square':'circle'}" data-slot="avatar" data-size="${size}" data-image-state="${src?'loading':'fallback'}" role="img" aria-label="${E(label)}" style="${styles(tokensOf(c))}"><span class="pp-avatar-fallback" data-slot="avatar-fallback" aria-hidden="true">${fallback}</span>${src?`<span class="pp-avatar-photo ${samplePhoto?'sample-portrait':''}" aria-hidden="true"><img class="pp-avatar-image" data-slot="avatar-image" src="${E(src)}" alt="" aria-hidden="true" draggable="false" decoding="async"></span>`:''}${badge!=='none'?`<span class="pp-avatar-badge badge-${badge}" data-slot="avatar-badge" aria-hidden="true">${badge==='icon'?F.icon(icon,parseFloat(F.resolve('component.avatar.badge.mark.'+size))):''}</span>`:''}</span>`;
 };
 F.avatarGroupTokens=(c={})=>{
  const tokens=F.avatarTokens({...c,badge:'none',online:false});
  tokens.push('component.avatar.group.overlap','component.avatar.ring','component.avatar.ring.width');
  if(overflowOf(c.overflow)>0){tokens.push('component.avatar.group.count.background','component.avatar.group.count.foreground');if(c.countStyle==='icon')tokens.push('component.avatar.group.icon.'+sizeOf(c));}
  return [...new Set(tokens)];
 };
 F.avatarGroup=(c={})=>{
  const count=countOf(c.count),overflow=overflowOf(c.overflow),size=sizeOf(c);
  const people=samples;
  const groupTokens={...tokensOf({...c,badge:'none',online:false}),ring:'component.avatar.ring','ring-width':'component.avatar.ring.width',overlap:'component.avatar.group.overlap',
   'count-background':'component.avatar.group.count.background','count-foreground':'component.avatar.group.count.foreground','count-icon':'component.avatar.group.icon.'+size};
  const avatars=people.slice(0,count).map((person,index)=>F.avatar({...c,sample:index,name:person.name,initials:person.initials,src:person.src,badge:'none',online:false})).join('');
  const remainder=overflow?`<span class="pp-avatar-count" data-slot="avatar-group-count" role="img" aria-label="${overflow} more ${overflow===1?'person':'people'}"><span aria-hidden="true">${c.countStyle==='icon'?F.icon('plus',parseFloat(F.resolve('component.avatar.group.icon.'+size))):'+'+overflow}</span></span>`:'';
  return `<span class="pp-avatar-group" data-slot="avatar-group" data-size="${size}" role="group" aria-label="${E(c.groupName||'People')}" style="${styles(groupTokens)}">${avatars}${remainder}</span>`;
 };
 F.wireAvatars=(root,registerCleanup)=>{
  const disposers=[];
  root.querySelectorAll('[data-slot="avatar-image"]').forEach(img=>{
   const avatar=img.closest('[data-slot="avatar"]');if(!avatar)return;
   const loaded=()=>{avatar.dataset.imageState='loaded';};
   const failed=()=>{avatar.dataset.imageState='fallback';};
   img.addEventListener('load',loaded);img.addEventListener('error',failed);
   if(img.complete)(img.naturalWidth>0?loaded:failed)();
   disposers.push(()=>{img.removeEventListener('load',loaded);img.removeEventListener('error',failed);});
  });
  const cleanup=()=>disposers.forEach(dispose=>dispose());
  if(typeof registerCleanup==='function')registerCleanup(cleanup);
  return cleanup;
 };
 document.getElementById('project-tokens').textContent=F.tokenCSS();
})(window.Forma);
